WITH toegang AS (SELECT COALESCE((SELECT CAST(json_extract(o.parameters, '$.toegang_dagen') AS INTEGER) FROM organisatie o WHERE o.soort = 'eigen' AND o.deleted_at IS NULL ORDER BY o.id LIMIT 1), 30) AS dagen), dagen AS (SELECT productie_id, MIN(datum) AS eerste, MAX(datum) AS laatste FROM activiteit WHERE deleted_at IS NULL GROUP BY productie_id), rollen AS (SELECT persoon_id, productie_id, group_concat(naam, ', ' ORDER BY naam) AS rollen FROM (SELECT DISTINCT t.persoon_id, a.productie_id, r.naam FROM toewijzing t JOIN activiteit a ON a.id = t.activiteit_id AND a.deleted_at IS NULL JOIN rol r ON r.id = t.rol_id AND r.deleted_at IS NULL WHERE t.deleted_at IS NULL AND t.state = 'bevestigd') GROUP BY persoon_id, productie_id) SELECT MIN(t.id) AS id, t.persoon_id, a.productie_id, p.titel AS productie, rl.rollen AS rollen, d.eerste AS vanaf, d.laatste AS laatste_dag, date(d.laatste, '+' || toegang.dagen || ' days') AS toegang_vervalt FROM toewijzing t JOIN activiteit a ON a.id = t.activiteit_id AND a.deleted_at IS NULL JOIN productie p ON p.id = a.productie_id AND p.deleted_at IS NULL JOIN dagen d ON d.productie_id = a.productie_id CROSS JOIN toegang LEFT JOIN rollen rl ON rl.persoon_id = t.persoon_id AND rl.productie_id = a.productie_id WHERE t.deleted_at IS NULL AND t.state = 'bevestigd' AND EXISTS (SELECT 1 FROM persoon pe WHERE pe.id = t.persoon_id AND pe.deleted_at IS NULL) GROUP BY t.persoon_id, a.productie_id HAVING date('now') <= toegang_vervalt
